+// Recovery reloads the durable receipt instead of trusting the recorded
+// `receipt_verified` flag. An interrupted run can leave a receipt on disk that no
+// longer matches the branch it is filed under, so selection must reject it even on
+// a schema 1 fork, where nothing but this verdict stands in front of landing.
+let staleNow = 0;
+const staleFork = forks.startFork({
+  projectRoot: project,
+  forkId: 'fork-stale-receipt',
+  title: 'Stale receipt proof',
+  objective: 'Prove recovery refuses a receipt that no longer matches its branch',
+  workflow,
+  baseRevision,
+  worktreeRoot: worktrees,
+  worktreeProvider: provider,
+  runBranch: fakeRun,
+  createdAt: '2026-07-13T14:00:00.000Z',
+  now: () => `2026-07-13T14:00:${String(staleNow++).padStart(2, '0')}.000Z`,
+}).fork;
+assert.equal(staleFork.schema_version, 1, 'this guard must cover legacy schema 1 forks');
+assert(staleFork.branches.every((branch) => branch.evidence_summary.receipt_verified));
+
+const receiptsDir = path.join(project, '.planning/operation-forks/fork-stale-receipt/receipts');
+const claudeReceipt = path.join(receiptsDir, 'branch-claude.json');
+const healthyReceipt = fs.readFileSync(claudeReceipt, 'utf8');
+// The sibling receipt is validly signed by the same fork key; it is simply bound to
+// another branch. This is mismatch, not corruption, so it cannot be caught by shape.
+fs.writeFileSync(claudeReceipt, fs.readFileSync(path.join(receiptsDir, 'branch-codex.json'), 'utf8'));
+
+const tampered = forks.loadFork(project, 'fork-stale-receipt');
+const tamperedBranch = tampered.branches.find((branch) => branch.branch_id === 'branch-claude');
+const staleEvidence = forks.verifyBranchEvidence(project, tampered, tamperedBranch);
+assert.equal(staleEvidence.verification.status, 'invalid');
+assert.equal(staleEvidence.verification.reason_code, 'EXECUTION_RECEIPT_DIGEST_MISMATCH');
+assert.equal(tamperedBranch.evidence_summary.receipt_verified, true,
+  'the recorded flag still claims verified, which is exactly what must not be trusted');
+assert.throws(() => forks.applySelection({
+  projectRoot: project, forkId: 'fork-stale-receipt', branchId: 'branch-claude',
+  expectedRevision: tampered.revision, actorId: 'actor-test',
+  idempotencyKey: 'idem-stale-1', reason: 'stale receipt',
+  now: () => '2026-07-13T14:30:00.000Z',
+}), (error) => error.code === 'FORK_RECEIPT_UNVERIFIED', 'a mismatched receipt must not be selectable');
+assert.equal(forks.loadFork(project, 'fork-stale-receipt').selection, null,
+  'a rejected selection must leave no durable trace');
+// The comparison surface must agree, so no operator or view is offered a winner that
+// rests on a receipt the fork can no longer verify.
+const staleComparison = forks.compareFork(tampered, { evidence: forks.forkEvidence(project, tampered) });
+const staleEntry = staleComparison.branches.find((branch) => branch.branch_id === 'branch-claude');
+assert.equal(staleEntry.comparable, false);
+assert(staleEntry.reasons.includes('fork-receipt-unverified'), 'the stale receipt must be named as the reason');
+assert.notEqual(staleComparison.recommendation, 'branch-claude');
+
+// Restoring the correct receipt is the only change, so acceptance proves the guard
